def zip_tuples(a, b):
    """The program dawnr proved in `t`, written in Python (checked against `t`, not itself proved).

    requires len(a) > 0
    requires len(b) > 0
    ensures  len(r) == len(a)
    ensures  forall i in [0, len(a)) . len(r[i]) == 2
    ensures  forall i in [0, len(a)) . r[i][0] == a[i]
    ensures  forall i in [0, len(a)) . r[i][1] == b[i % len(b)]

    Outside its `requires` it raises ValueError: nothing was proved there.
    """
    if not (_t_ints(a, 1)):
        raise TypeError('zip_tuples: `a` must be a list of integers; nothing was proved for anything else')
    if not (_t_ints(b, 1)):
        raise TypeError('zip_tuples: `b` must be a list of integers; nothing was proved for anything else')
    a = _t_tuple(a)
    b = _t_tuple(b)
    if not _t_requires(a, b):
        raise ValueError('zip_tuples: this input is outside what was proved (requires len(a) > 0; len(b) > 0)')
    _t_result = _t_core(a, b)
    return _t_shape(_t_result, ('list', 'tuple'))

def _t_core(a, b):
    r = ()
    i = 0
    # invariant: 0 <= i
    # invariant: i <= len(a)
    # invariant: len(r) == i
    # invariant: forall j in [0, i) . len(r[j]) == 2
    # invariant: forall j in [0, i) . r[j][0] == a[j]
    # invariant: forall j in [0, i) . r[j][1] == b[j % len(b)]
    # decreases: len(a) - i
    while (i < len(a)):
        r = (r + ((a[i], b[_t_mod(i, len(b))], ), ))
        i = (i + 1)
    return r

def _t_requires(a, b):
    try:
        return bool((len(a) > 0)) and bool((len(b) > 0))
    except (IndexError, ZeroDivisionError):   # a `requires` with no value here admits nothing
        return False

def _t_tuple(v):
    return tuple(_t_tuple(x) for x in v) if isinstance(v, (list, tuple)) else v

def _t_ints(v, depth):
    if depth == 0:
        return isinstance(v, int) and not isinstance(v, bool)
    return isinstance(v, (list, tuple)) and all(_t_ints(x, depth - 1) for x in v)

def _t_shape(v, kinds):
    if not isinstance(v, tuple):
        return v
    inner = [_t_shape(x, kinds[1:] or kinds[-1:]) for x in v]
    return tuple(inner) if kinds[0] == "tuple" else inner

def _t_mod(x, y):
    return x % abs(y)          # Euclidean, as t defines it (SPEC.md)

def _t_div(x, y):
    return (x - x % abs(y)) // y

